edits.replace:
stack({ id: "mui", width: side * 0.6, height: side * 0.6, motion: "none" },
  ["o", "b", "l", "w", "p", "k"].map((letter) => {
    // Her eyes look about over her face: under them, her face (one path with it, no seam).
    const eye = letter === "w" || letter === "p";
    return path({ id: `mui-${letter}`, d: letter === "b" ? pixels("b") + pixels("w") + pixels("p") : pixels(letter), fill: palette[letter],
                  viewBox: "0 0 16 16", width: side * 0.6, height: side * 0.6,
                  translateX: eye ? lookX : 0, translateY: eye ? lookY : 0, motion: "none" });
  })),

// Mui looks at the pointer: from the middle of her circle toward it, one of her pixels each way at most.
const lookX = signal(0, "page.look-x");
const lookY = signal(0, "page.look-y");
const pixel = (side * 0.6) / 16;
let circle = "";  // the O's path in the tree, found once
const lookAt = (event: { x: number; y: number }) => {
  if (!circle) circle = snapshot({}).nodes.find((node: { id: string }) => node.id.endsWith("/o")).id;
  const [x, y, width, height] = snapshot({ root: circle, depth: 0 }).nodes[0].bounds;
  const dx = event.x - (x + width / 2), dy = event.y - (y + height / 2);
  const reach = Math.max(Math.abs(dx), Math.abs(dy), side / 2);
  lookX.set(Math.round(dx / reach) * pixel);
  lookY.set(Math.round(dy / reach) * pixel);
};
const lookAhead = () => { lookX.set(0); lookY.set(0); };

const resting = eq(state, "rest");

